import{_ as t,o as e,c as o,a2 as r}from"./chunks/framework.Crpw6aS5.js";const d=JSON.parse('{"title":"冠军国际纸业 Champion International","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/冠军国际纸业.md","filePath":"03_companies/冠军国际纸业.md"}'),l={name:"03_companies/冠军国际纸业.md"};function n(i,a,h,s,_,c){return e(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="冠军国际纸业-champion-international" tabindex="-1">冠军国际纸业 Champion International <a class="header-anchor" href="#冠军国际纸业-champion-international" aria-label="Permalink to &quot;冠军国际纸业 Champion International&quot;">​</a></h1><h2 id="公司简介" tabindex="-1">公司简介 <a class="header-anchor" href="#公司简介" aria-label="Permalink to &quot;公司简介&quot;">​</a></h2><p>冠军国际纸业（Champion International Corporation）是美国大型林产品企业，主营纸张、纸浆和木材业务，在蒙大拿州等地拥有大片森林资源。公司于2000年被国际纸业收购。在巴菲特1990年代初持有期间，公司遭遇严重火灾损失和林产品行业周期性衰退，处境艰难。</p><h2 id="投资时间线" tabindex="-1">投资时间线 <a class="header-anchor" href="#投资时间线" aria-label="Permalink to &quot;投资时间线&quot;">​</a></h2><ul><li><strong>1989年</strong>：伯克希尔开始买入冠军国际纸业股份</li><li><strong>1990年代初</strong>：持有期间，公司遭遇重大森林火灾，造成巨额损失</li><li><strong>1995年</strong>：伯克希尔出售所持冠军国际全部股份</li></ul><h2 id="巴菲特评价" tabindex="-1">巴菲特评价 <a class="header-anchor" href="#巴菲特评价" aria-label="Permalink to &quot;巴菲特评价&quot;">​</a></h2><p>巴菲特对冠军国际的投资是他处理&quot;困境公司&quot;的典型案例。在1990年致股东信中，巴菲特详细讨论了这项投资，认为公司拥有真实的护城河——大片自有森林、相对较低的木材成本优势——但这些优势无法抵御整个行业产能过剩和宏观经济衰退带来的冲击。</p><p>巴菲特承认自己在行业周期判断上犯了错误，持有期间林产品业务利润大幅下滑，最终不得不承担减值损失。他总结说，即使拥有护城河的公司，当行业整体陷入困境时，股东也需要承受资本回报不佳的代价。这一案例后来成为巴菲特强调&quot;好行业&quot;重要性的反面教材——护城河再宽，也难以对抗一个夕阳产业。</p><h2 id="关键语录" tabindex="-1">关键语录 <a class="header-anchor" href="#关键语录" aria-label="Permalink to &quot;关键语录&quot;">​</a></h2><blockquote><p>&quot;我们的冠军国际投资案例说明，即使一家公司拥有真实的竞争优势，当它所处的行业遭遇产能过剩和经济衰退时，股东仍然会遭受损失。在周期性行业里，即使买入估值看起来合理，也可能是一个糟糕的决策。&quot;</p></blockquote><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/1989年/翻译.html">/01_letters/1989年/翻译</a></li><li><a href="/01_letters/1995年/翻译.html">/01_letters/1995年/翻译</a></li><li><a href="/01_letters/翻译.html">/01_letters//翻译</a></li><li><a href="/01_letters/翻译.html">/01_letters//翻译</a></li></ul>',13)])])}const u=t(l,[["render",n]]);export{d as __pageData,u as default};
